def fingerprint(text):
    value = 2166136261
    for char in text.strip():
        value = ((value ^ ord(char)) * 16777619) & 0xffffffff
    return f"{value:08x}"

def witness_suite(identifier):
    path, klass, method = identifier.split("::")
    source = ROOT / path
    if not source.is_file():
        raise AssertionError(f"Testigo inexistente: {path}")
    name = "factory_verificacion13_" + source.stem
    spec = importlib.util.spec_from_file_location(name, source)
    if spec is None or spec.loader is None:
        raise AssertionError(f"Testigo ilegible: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[name] = module
    spec.loader.exec_module(module)
    suite = unittest.defaultTestLoader.loadTestsFromName(f"{klass}.{method}", module)
    if suite.countTestCases() != 1:
        raise AssertionError(f"Testigo inválido: {identifier}")
    return suite

class VerificacionFactory13Tests(unittest.TestCase):
    def test_70_filas_unicas_con_ancla_documental_exacta(self):
        self.assertEqual(len(ROWS), 70)
        self.assertEqual(len({r[0] for r in ROWS}), 70)
        for identifier, witness, kind, fp, statement in ROWS:
            with self.subTest(row=identifier):
                m = re.fullmatch(r"(docs/[^:]+):L([1-9][0-9]*)-U([1-9][0-9]*)", identifier)
                self.assertIsNotNone(m)
                path, line_number, _ = m.groups()
                lines = (ROOT / path).read_text(encoding="utf-8").splitlines()
                self.assertLessEqual(int(line_number), len(lines))
                self.assertEqual(fingerprint(lines[int(line_number)-1]), fp)
                self.assertTrue(statement)
                self.assertIn(kind, {"RECOVERY_SINTETICO", "DOCUMENTO_Y_GATE_LOCAL", "VALIDACION_DE_CAPACIDADES"})

    def test_testigos_ejecutan_regresiones_de_comportamiento_real(self):
        for witness in sorted({r[1] for r in ROWS}):
            with self.subTest(witness=witness):
                result = unittest.TestResult()
                witness_suite(witness).run(result)
                detail = "\n".join(f"{t}: {message}" for t, message in result.errors + result.failures)
                self.assertTrue(result.wasSuccessful(), detail)
                self.assertEqual(result.testsRun, 1)

    def test_informe_enlaza_70_filas_sin_promover_la_matriz(self):
        report = REPORT.read_text(encoding="utf-8")
        self.assertIn("70 filas", report)
        self.assertIn("NO_VERIFICABLE", report)
        self.assertIn("no acredita", report.lower())
        self.assertNotIn("CUBIERTO", report.split("## Alcance y límites", 1)[0])
        for identifier, witness, kind, fp, _ in ROWS:
            with self.subTest(row=identifier):
                self.assertEqual(report.count("`" + identifier + "`"), 1)
                self.assertIn("`" + witness + "`", report)
                self.assertIn(fp, report)

    def test_negativos_detectan_drift_y_testigo_inexistente(self):
        identifier, _, kind, fp, _ = ROWS[0]
        path, location = identifier.split(":L")
        source_line = (ROOT / path).read_text(encoding="utf-8").splitlines()[int(location.split("-")[0])-1]
        self.assertEqual(fingerprint(source_line), fp)
        self.assertNotEqual(fingerprint(source_line+" [mutación]"), fp)
        with self.assertRaises(AssertionError):
            witness_suite("tests/test_inexistente_13.py::NoExiste::test_inexistente")
        self.assertEqual(kind, "RECOVERY_SINTETICO")

if __name__ == "__main__":
    unittest.main()
